//! Parity tests against the Go original (`github.com/junhinhow/charm-nav`).
//!
//! The golden file is generated by the Go program in
//! `reference/go/charm-nav/cmd/parity`, which exercises the same public API
//! in the same order:
//!
//! ```text
//! cargo run -p charm-parity --bin parity -- gen \
//!     crates/charm-nav/tests/golden/nav.txt -- \
//!     go run ./reference/go/charm-nav/cmd/parity
//! ```

use std::fmt::Write as _;

use charm_nav::{Breadcrumb, Sidebar, Tabs};
use charm_parity::assert_golden;

/// Formats the result of `add` the same way as the Go parity program.
fn add_result(index: Option<usize>) -> String {
    match index {
        Some(i) => format!("add={i}"),
        None => "add=none".to_owned(),
    }
}

/// Builds the very same output as the Go parity program.
#[allow(clippy::too_many_lines)]
fn build_output() -> String {
    let mut out = String::new();

    let mut tabs = Tabs::new(&["Home", "Settings", "About"]);

    let _ = writeln!(out, "=== tabs padrao ===");
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "active={}", tabs.active());
    let _ = writeln!(out, "items={}", tabs.items().join(","));

    let _ = writeln!(out, "=== tabs apos next ===");
    tabs.next();
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "active={}", tabs.active());

    let _ = writeln!(out, "=== tabs apos previous ===");
    tabs.previous();
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "active={}", tabs.active());

    let _ = writeln!(out, "=== tabs previous no inicio ===");
    tabs.previous();
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "active={}", tabs.active());

    let _ = writeln!(out, "=== tabs set active fora do intervalo ===");
    tabs.set_active(99);
    let _ = writeln!(out, "active={}", tabs.active());

    let _ = writeln!(out, "=== tabs set active valido ===");
    tabs.set_active(2);
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "active={}", tabs.active());

    let _ = writeln!(out, "=== tabs add ===");
    let _ = writeln!(out, "{}", add_result(tabs.add(&["Ajuda", "Contato"])));
    let _ = writeln!(out, "{}", tabs.render());
    let _ = writeln!(out, "items={}", tabs.items().join(","));

    let _ = writeln!(out, "=== tabs add vazio ===");
    let _ = writeln!(out, "{}", add_result(tabs.add(&[])));

    let _ = writeln!(out, "=== tabs remove anterior a ativa ===");
    let _ = writeln!(out, "removed={}", tabs.remove(0));
    let _ = writeln!(out, "active={}", tabs.active());
    let _ = writeln!(out, "items={}", tabs.items().join(","));

    let _ = writeln!(out, "=== tabs remove invalido ===");
    let _ = writeln!(out, "removed={}", tabs.remove(99));
    let _ = writeln!(out, "items={}", tabs.items().join(","));

    let _ = writeln!(out, "=== tabs remove ultima ativa ===");
    tabs.set_active(3);
    let _ = writeln!(out, "removed={}", tabs.remove(3));
    let _ = writeln!(out, "active={}", tabs.active());
    let _ = writeln!(out, "{}", tabs.render());

    let _ = writeln!(out, "=== tabs vazio ===");
    let mut empty_tabs = Tabs::new(&[]);
    let _ = writeln!(out, "{}", empty_tabs.render());
    empty_tabs.next();
    empty_tabs.previous();
    let _ = writeln!(out, "active={}", empty_tabs.active());

    let mut sidebar = Sidebar::new(&["Dashboard", "Users", "Settings", "Logs"]);

    let _ = writeln!(out, "=== sidebar padrao ===");
    sidebar.set_selected(1);
    let _ = writeln!(out, "{}", sidebar.render());
    let _ = writeln!(out, "selected={}", sidebar.selected());

    let _ = writeln!(out, "=== sidebar apos next ===");
    sidebar.next();
    let _ = writeln!(out, "{}", sidebar.render());
    let _ = writeln!(out, "selected={}", sidebar.selected());

    let _ = writeln!(out, "=== sidebar apos previous ===");
    sidebar.previous();
    let _ = writeln!(out, "{}", sidebar.render());
    let _ = writeln!(out, "selected={}", sidebar.selected());

    let _ = writeln!(out, "=== sidebar previous no inicio ===");
    let mut fresh = Sidebar::new(&["Dashboard", "Users", "Settings", "Logs"]);
    fresh.previous();
    let _ = writeln!(out, "{}", fresh.render());
    let _ = writeln!(out, "selected={}", fresh.selected());

    let _ = writeln!(out, "=== sidebar set selected fora do intervalo ===");
    fresh.set_selected(42);
    let _ = writeln!(out, "selected={}", fresh.selected());

    let _ = writeln!(out, "=== sidebar largura e cursor customizados ===");
    let mut custom = Sidebar::new(&["Dashboard", "Users"]);
    custom.width = 30;
    custom.cursor = "> ".to_string();
    let _ = writeln!(out, "{}", custom.render());

    let _ = writeln!(out, "=== sidebar truncamento ===");
    let mut narrow = Sidebar::new(&["Dashboard", "Configuracoes avancadas"]);
    narrow.width = 12;
    narrow.set_selected(1);
    let _ = writeln!(out, "{}", narrow.render());

    let _ = writeln!(out, "=== sidebar largura minima ===");
    let mut tiny = Sidebar::new(&["Dashboard", "Users"]);
    tiny.width = 0;
    let _ = writeln!(out, "{}", tiny.render());
    tiny.width = 3;
    let _ = writeln!(out, "{}", tiny.render());

    let _ = writeln!(out, "=== sidebar cursor maior que a area ===");
    let mut huge = Sidebar::new(&["Aa", "Bb"]);
    huge.width = 5;
    huge.cursor = ">>>>>>>>>>".to_string();
    let _ = writeln!(out, "{}", huge.render());

    let _ = writeln!(out, "=== sidebar cursor vazio ===");
    let mut no_cursor = Sidebar::new(&["Dashboard", "Users"]);
    no_cursor.cursor = String::new();
    let _ = writeln!(out, "{}", no_cursor.render());

    let _ = writeln!(out, "=== sidebar add ===");
    let _ = writeln!(out, "{}", add_result(sidebar.add(&["Ajuda"])));
    let _ = writeln!(out, "{}", sidebar.render());
    let _ = writeln!(out, "items={}", sidebar.items().join(","));

    let _ = writeln!(out, "=== sidebar remove anterior ao selecionado ===");
    sidebar.set_selected(2);
    let _ = writeln!(out, "removed={}", sidebar.remove(0));
    let _ = writeln!(out, "selected={}", sidebar.selected());
    let _ = writeln!(out, "{}", sidebar.render());

    let _ = writeln!(out, "=== sidebar remove o selecionado ===");
    let selected = sidebar.selected();
    let _ = writeln!(out, "removed={}", sidebar.remove(selected));
    let _ = writeln!(out, "selected={}", sidebar.selected());
    let _ = writeln!(out, "{}", sidebar.render());

    let _ = writeln!(out, "=== sidebar remove ultimo selecionado ===");
    sidebar.set_selected(2);
    let _ = writeln!(out, "removed={}", sidebar.remove(2));
    let _ = writeln!(out, "selected={}", sidebar.selected());

    let _ = writeln!(out, "=== sidebar vazio ===");
    let empty_sidebar = Sidebar::new(&[]);
    let _ = writeln!(out, "{}", empty_sidebar.render());
    let _ = writeln!(out, "selected={}", empty_sidebar.selected());

    let mut breadcrumb = Breadcrumb::new(&["Home", "Settings"]);

    let _ = writeln!(out, "=== breadcrumb padrao ===");
    breadcrumb.push("Profile");
    let _ = writeln!(out, "{}", breadcrumb.render());
    let _ = writeln!(out, "items={}", breadcrumb.items().join(","));

    let _ = writeln!(out, "=== breadcrumb apos pop ===");
    let _ = writeln!(out, "pop={}", breadcrumb.pop());
    let _ = writeln!(out, "{}", breadcrumb.render());

    let _ = writeln!(out, "=== breadcrumb add ===");
    let _ = writeln!(out, "{}", add_result(breadcrumb.add(&["Config", "Perfil"])));
    let _ = writeln!(out, "{}", breadcrumb.render());

    let _ = writeln!(out, "=== breadcrumb remove ===");
    let _ = writeln!(out, "removed={}", breadcrumb.remove(1));
    let _ = writeln!(out, "items={}", breadcrumb.items().join(","));

    let _ = writeln!(out, "=== breadcrumb pop vazio ===");
    let mut empty_breadcrumb = Breadcrumb::new(&[]);
    let _ = writeln!(out, "pop={}", empty_breadcrumb.pop());
    let _ = writeln!(out, "{}", empty_breadcrumb.render());

    out
}

#[test]
fn nav_matches_the_go_original() {
    assert_golden("nav", &build_output());
}
